static int amp_adsr_page(void)
{
    for (int p = 0; p < pg.n; p++)
        if (!strcmp(pg.title[p], "AMP ADSR"))
            return p;
    return -1;
}

int main(void)
{
    int p, i;
    boot();
    assert(engine_bass_is_wobble(0) && "DEV fixture: 303A is WBL1");
    ui.view = V_PART;
    ui.part = PART_303A;
    build_pages();
    p = amp_adsr_page();
    assert(p >= 0 && "Miami AMP ADSR page exists");
    assert(pg.r[p][0].c == W_ATTACK && pg.r[p][1].c == W_DECAY);
    assert(pg.r[p][2].c == W_SUSTAIN && pg.r[p][3].c == W_RELEASE);
    assert(pg.r[p][0].b == 0 && "303A voice index");
    for (i = 0; i < 4; i++) {
        const x0x_param_t *d = engine_param(T_303, 0, pg.r[p][i].c);
        assert(d && d->name[0]);
    }
    *page_of(V_PART) = (uint8_t)p;
    build_pages();
    for (i = 0; i < 4; i++)
        assert(smc_same(smc_knob_target(i), pg.r[p][i]));
    puts("PASS miami amp adsr smc knobs");
    return 0;
}

/* SPDX-License-Identifier: GPL-3.0-only */
#pragma once
#include "bass303.h"
#include "wobble_config.h"
#include <stddef.h>

#define SYNTH_ENGINE_303 1u
#define SYNTH_SCHEMA_303 1u
#define SYNTH_SAMPLE_RATE 44100u
#define SYNTH_MAX_BLOCK 256u
/* Caller-owned contexts and descriptors must outlive the slot. No allocation,
 * filesystem, UI or project-memory access is permitted in backend callbacks. */
typedef struct {
    uint32_t id;
    uint16_t schema, nparams;
    void (*init)(void *);
    void (*render)(void *, float *, int);
    void (*note)(void *, int, int, int, int);
    void (*off)(void *);
    void (*panic)(void *);
    void (*set)(void *, int, int);
    void (*transport)(void *, int);
    int (*active)(const void *);
    int (*idle)(const void *);
    void (*lite)(void *, int);
} synth_ops_t;
typedef struct { const synth_ops_t *ops; void *context; } synth_binding_t;
typedef struct { uint32_t engine; uint16_t schema, param; } synth_param_key_t;
typedef struct {
    synth_binding_t active, pending;
    volatile uint8_t requested, acknowledged;
    uint8_t running, lite;
} synth_slot_t;
/* Same-core main-loop producer / audio ISR consumer only. Publishing a single
 * byte occurs last; pending fields cannot be reused until acknowledgement.
 * Compiler fences suffice on this single-core interrupt contract. Other thread
 * models must supply a synchronized external queue (host tests are sequential). */
#define SYNTH_FENCE() __asm__ volatile("" ::: "memory")
static inline int synth_valid(synth_binding_t b)
{
    return b.context && b.ops && b.ops->id && b.ops->schema && b.ops->init &&
        b.ops->render && b.ops->note && b.ops->off && b.ops->panic && b.ops->set &&
        b.ops->transport && b.ops->active && b.ops->idle && b.ops->lite;
}
static inline int synth_init(synth_slot_t *s, synth_binding_t b)
{
    if (!s || !synth_valid(b)) return 0;
    s->active = b; s->pending = b; s->requested = s->acknowledged = 0;
    s->running = s->lite = 0; b.ops->init(b.context); return 1;
}
/* Alternate descriptors are test-only until native fit, lifecycle and identity
 * qualification. There is deliberately no public engine registry/menu. */
static inline int synth_request(synth_slot_t *s, synth_binding_t b, uint8_t *ticket)
{
    if (!synth_valid(b) || s->requested != s->acknowledged) return 0;
#ifndef X0X_SYNTH_HOST_TEST
    if ((b.ops->id != SYNTH_ENGINE_303 || b.ops->schema != SYNTH_SCHEMA_303)
#if X0X_DEV_WOBBLE
        && (b.ops->id != 0x57424c31u || b.ops->schema != 1
            || b.ops->nparams != WOBBLE_EXPERIMENT_NPARAMS)
#endif
       ) return 0;
#endif
    SYNTH_FENCE(); s->pending = b; SYNTH_FENCE();
    s->requested = (uint8_t)(s->requested + 1u);
    if (ticket) *ticket = s->requested;
    return 1;
}
/* Invoke only at the audio command boundary, before notes/locks/render. New
 * context is already initialized; panic clears notes but retains its settings. */
static inline int synth_boundary(synth_slot_t *s)
{
    uint8_t ticket = s->requested;
    if (ticket == s->acknowledged) return 0;
    SYNTH_FENCE();
    s->active.ops->panic(s->active.context);
    if (s->active.context != s->pending.context || s->active.ops != s->pending.ops)
        s->pending.ops->panic(s->pending.context);
    s->active = s->pending;
    s->active.ops->lite(s->active.context, s->lite);
    s->active.ops->transport(s->active.context, s->running);
    SYNTH_FENCE(); s->acknowledged = ticket; return 1;
}
static inline int synth_set(synth_slot_t *s, synth_param_key_t k, int value)
{
    if (k.engine != s->active.ops->id || k.schema != s->active.ops->schema ||
        k.param >= s->active.ops->nparams) return 0;
    s->active.ops->set(s->active.context, k.param, value); return 1;
}
static inline void synth_render(synth_slot_t *s, float *out, int n)
{ s->active.ops->render(s->active.context, out, n); }
static inline void synth_note(synth_slot_t *s, int n, int a, int sl, int v)
{ s->active.ops->note(s->active.context, n, a, sl, v); }
static inline void synth_off(synth_slot_t *s) { s->active.ops->off(s->active.context); }
static inline void synth_transport(synth_slot_t *s, int running)
{
    s->running = !!running;
    if (!running) s->active.ops->panic(s->active.context);
    s->active.ops->transport(s->active.context, s->running);
}
static inline void synth_lite(synth_slot_t *s, int lite)
{ s->lite = !!lite; s->active.ops->lite(s->active.context, lite); }
static inline int synth_active(const synth_slot_t *s)
{ return s->active.ops ? s->active.ops->active(s->active.context) : 0; }
static inline int synth_idle(const synth_slot_t *s)
{ return s->active.ops ? s->active.ops->idle(s->active.context) : 1; }

static void synth303_init(void *p) { bass303_init(p); }
static void synth303_render(void *p, float *o, int n) { bass303_render(p, o, n); }
static void synth303_note(void *p, int n, int a, int sl, int v) { bass303_note_on_velocity(p,n,a,sl,v); }
static void synth303_off(void *p) { bass303_note_off(p); }
static void synth303_panic(void *p) { bass303_all_off(p); }
static void synth303_set(void *p, int i, int v) { bass303_set(p,i,v); }
static void synth303_transport(void *p, int run) { (void)p; (void)run; }
static int synth303_active(const void *p) { return ((const bass303_t *)p)->gate; }
static int synth303_idle(const void *p) { return ((const bass303_t *)p)->idle; }
static void synth303_lite(void *p, int on) { bass303_set_lite(p,on); }
static const synth_ops_t synth303_ops = {
    SYNTH_ENGINE_303, SYNTH_SCHEMA_303, BASS303_NPARAMS,
    synth303_init, synth303_render, synth303_note, synth303_off, synth303_panic,
    synth303_set, synth303_transport, synth303_active, synth303_idle, synth303_lite
};
static inline synth_binding_t synth303_binding(bass303_t *context)
{ synth_binding_t b = { &synth303_ops, context }; return b; }
static inline synth_param_key_t synth303_key(unsigned param)
{ synth_param_key_t k = { SYNTH_ENGINE_303, SYNTH_SCHEMA_303, (uint16_t)param }; return k; }

/* SPDX-License-Identifier: GPL-3.0-only */
/* Firmware editor.c: SMP_BEGIN must keep last-good until the first WRITE. */
#include <assert.h>
#include <stdio.h>
#include <string.h>
#define X0X_HOST 1
#define BOARD_SMK37 0
#define X0X_BLE 0
#define X0X_DRUM_TABLES_DEFINE              /* x0x.h pulls drum909 tanh helpers */
#include "../../firmware/src/app/x0x.h"

static uint8_t flash_image[0x100000];
#define SMP_USER_XIP(k) (flash_image + SMP_USER_OFF(k))
#include "../../firmware/src/app/slots.c"
project_t proj, project_stage;
static uint32_t fm1_ms, fm1_crash[2];
static struct { uint32_t failed, pending; } bootguard;
static struct { unsigned ota_req, uboot_req; } usb;
static int flash_ok = 1, flash_erases;
static uint8_t frame[640], reply[800];
static uint32_t frame_n, reply_n;
static void fm1_irq_off(void) {}
static void fm1_irq_on(void) {}
static void fm1_wdt_feed(void) {}
static void audio_silence(void) {}
static void fl_inval(uint32_t off, uint32_t n) { (void)off; (void)n; }
static int fl_write(uint32_t off, const void *p, uint32_t n)
{
    assert(off + n <= sizeof flash_image);
    memcpy(flash_image + off, p, n);
    return 0;
}
static int fl_erase4k(uint32_t off, uint32_t *took)
{
    assert(off + 4096 <= sizeof flash_image);
    memset(flash_image + off, 255, 4096);
    *took = 1;
    flash_erases++;
    return 0;
}
static int fl_read(uint32_t off, void *dst, uint32_t n)
{
    assert(off + n <= sizeof flash_image);
    memcpy(dst, flash_image + off, n);
    return 0;
}
static uint8_t *fm1_xip_ptr(uint32_t off)
{
    assert(off < sizeof flash_image);
    return flash_image + off;
}
static int store_stage_held(void) { return 0; }
static uint8_t *store_stage_lock(uint32_t *cap)
{
    static uint8_t buf[64];
    if (cap)
        *cap = sizeof buf;
    return buf;
}
static void store_stage_unlock(void) {}
static uint32_t st_crc32(const uint8_t *p, uint32_t n)
{
    uint32_t c = ~0u, b;
    while (n--) {
        c ^= *p++;
        for (b = 0; b < 8; b++)
            c = c & 1 ? (c >> 1) ^ 0xEDB88320u : c >> 1;
    }
    return ~c;
}
void engine_brk_loops(void) {}
void engine_brk_drop_range(const uint8_t *base, uint32_t nbytes) { (void)base; (void)nbytes; }
void ui_say(const char *a, const char *b) { (void)a; (void)b; }
int ui_boot_flash_busy(void) { return 0; }
int ui_project_busy(void) { return 0; }
int ui_project_begin(void) { return 0; }
void ui_project_end(int apply) { (void)apply; }
int ui_project_save(void) { return 0; }
int ui_project_load(void) { return 0; }
int ui_project_reset(void) { return 0; }
void project_capture_stage(void) {}
void project_file_header(uint8_t *h) { memset(h, 0, PROJECT_FILE_HDR); }
int project_file_validate(const uint8_t *h) { (void)h; return 0; }
static int ota_wire_send(const uint8_t *p, uint32_t n)
{
    assert(n <= sizeof reply);
    memcpy(reply, p, n);
    reply_n = n;
    return 0;
}
static int ota_frame_get(const uint8_t **p, uint32_t *n)
{
    *p = frame;
    *n = frame_n;
    return frame_n != 0;
}
static void ota_frame_done(void) { frame_n = 0; }
static uint8_t host_main_scratch[4096] __attribute__((aligned(4)));
#define ED_SMP_SCRATCH (host_main_scratch + 0xD00)
#include "../../firmware/src/app/editor.c"

static void request(uint8_t cmd, const uint8_t *p, uint32_t n)
{
    assert(n + 4 <= sizeof frame);
    frame[0] = ED_HDR0;
    frame[1] = ED_HDR1;
    frame[2] = ED_HDR2;
    frame[3] = cmd;
    if (n)
        memcpy(frame + 4, p, n);
    frame_n = n + 4;
    reply_n = 0;
    ed_service();
    assert(!frame_n);
    assert(reply_n >= 6 && reply[0] == 0xF0 && reply[4] == cmd && reply[reply_n - 1] == 0xF7);
}
static uint32_t pack(const uint8_t *p, uint32_t n, uint8_t *out)
{
    uint32_t i, j, pos = 0;
    for (i = 0; i < n; i += 7) {
        uint32_t m = pos++;
        out[m] = 0;
        for (j = 0; j < 7 && i + j < n; j++) {
            out[m] |= (p[i + j] >> 7) << j;
            out[pos++] = p[i + j] & 127;
        }
    }
    return pos;
}
static void u21(uint8_t *p, uint32_t n)
{
    p[0] = n & 127;
    p[1] = n >> 7 & 127;
    p[2] = n >> 14 & 127;
}

static void load_good(void)
{
    uint8_t header[512], data[32], a[600];
    smp_user_hdr_t *h = (smp_user_hdr_t *)header;
    uint32_t n, off, i;
    memset(header, 0, sizeof header);
    memset(data, 0x5A, sizeof data);
    h->magic = SMP_USER_MAGIC;
    h->version = 1;
    h->nz = 1;
    memcpy(h->name, "GOODLOOP", 8);
    h->data_len = sizeof data;
    h->zone[0].n = 64;
    h->zone[0].rate = 65536;
    h->crc = st_crc32(data, sizeof data);
    a[0] = 0;
    request(ED_SMP_BEGIN, a, 1);
    assert(reply[6] == 0);
    for (off = 512; off < 512 + sizeof data; off += 256) {
        uint32_t chunk = sizeof data - (off - 512);
        if (chunk > 256)
            chunk = 256;
        a[0] = 0;
        u21(a + 1, off);
        n = pack(data + (off - 512), chunk, a + 4);
        request(ED_SMP_WRITE, a, n + 4);
        assert(reply[9] == 0);
    }
    a[0] = 0;
    n = pack(header, 512, a + 1);
    request(ED_SMP_END, a, n + 1);
    assert(reply[6] == 0 && usr_nz[0] == 1);
    for (i = 0; i < 8; i++)
        assert(((const smp_user_hdr_t *)(flash_image + SMP_USER_OFF(0)))->name[i] == "GOODLOOP"[i]);
}

int main(void)
{
    uint8_t a[600], before[4096], data[32], header[512];
    uint32_t n, off;
    int erases_before;
    smp_user_hdr_t *h = (smp_user_hdr_t *)header;
    memset(flash_image, 0xFF, sizeof flash_image);
    load_good();
    memcpy(before, flash_image + SMP_USER_OFF(0), sizeof before);
    erases_before = flash_erases;

    a[0] = 0;
    request(ED_SMP_BEGIN, a, 1);
    assert(reply[6] == 0);
    assert(usr_nz[0] == 1);
    assert(flash_erases == erases_before);
    assert(!memcmp(before, flash_image + SMP_USER_OFF(0), sizeof before));
    puts("smp begin-cancel: BEGIN alone keeps last-good ok");

    /* BEGIN then END with no WRITE must refuse — NOR cannot rewrite a live header. */
    memset(header, 0, sizeof header);
    h->magic = SMP_USER_MAGIC;
    h->version = 1;
    h->nz = 1;
    memcpy(h->name, "NEWNAME1", 8);
    h->data_len = 32;
    h->zone[0].n = 64;
    h->zone[0].rate = 65536;
    h->crc = st_crc32((const uint8_t *)(flash_image + SMP_USER_OFF(0) + 512), 32);
    a[0] = 0;
    request(ED_SMP_BEGIN, a, 1);
    assert(reply[6] == 0);
    a[0] = 0;
    n = pack(header, 512, a + 1);
    request(ED_SMP_END, a, n + 1);
    assert(reply[6] == 6);
    assert(usr_nz[0] == 1);
    assert(!memcmp(before, flash_image + SMP_USER_OFF(0), sizeof before));
    puts("smp begin-cancel: END without WRITE refuses ok");

    /* Mid-WRITE erases sector 0; next BEGIN restores from FL_SMPV shadow. */
    memset(data, 0x5A, sizeof data);
    memset(header, 0, sizeof header);
    h->magic = SMP_USER_MAGIC;
    h->version = 1;
    h->nz = 1;
    memcpy(h->name, "GOODLOOP", 8);
    h->data_len = sizeof data;
    h->zone[0].n = 64;
    h->zone[0].rate = 65536;
    h->crc = st_crc32(data, sizeof data);
    a[0] = 0;
    request(ED_SMP_BEGIN, a, 1);
    assert(reply[6] == 0);
    off = 512;
    a[0] = 0;
    u21(a + 1, off);
    n = pack(data, sizeof data, a + 4);
    request(ED_SMP_WRITE, a, n + 4);
    assert(reply[9] == 0);
    assert(!memcmp(flash_image + SMP_USER_OFF(0) + 512, data, sizeof data));
    assert(usr_nz[0] == 0);
    a[0] = 0;
    request(ED_SMP_BEGIN, a, 1);
    assert(reply[6] == 0);
    assert(usr_nz[0] == 1);
    assert(!memcmp(before, flash_image + SMP_USER_OFF(0), sizeof before));
    puts("smp begin-cancel: mid-WRITE abandon restores last-good ok");

    /* Failed END (CRC) restores last-good. */
    a[0] = 0;
    request(ED_SMP_BEGIN, a, 1);
    off = 512;
    a[0] = 0;
    u21(a + 1, off);
    memset(data, 0xA5, sizeof data);
    n = pack(data, sizeof data, a + 4);
    request(ED_SMP_WRITE, a, n + 4);
    assert(reply[9] == 0);
    a[0] = 0;
    n = pack(header, 512, a + 1);   /* header CRC still matches old 0x5A data */
    request(ED_SMP_END, a, n + 1);
    assert(reply[6] == 3);
    assert(usr_nz[0] == 1);
    assert(!memcmp(before, flash_image + SMP_USER_OFF(0), sizeof before));
    puts("smp begin-cancel: failed END restores last-good ok");

    /* Multi-sector last-good: WRITE into 0x1000 then abandon must NOT leave
     * usr_nz set over a restored sector-0 header with wiped higher data. */
    {
        uint8_t big_hdr[512], big_data[5000], sec1_before[4096], chunk[256];
        smp_user_hdr_t *bh = (smp_user_hdr_t *)big_hdr;
        uint32_t base = SMP_USER_OFF(0);
        memset(flash_image, 0xFF, sizeof flash_image);
        memset(big_hdr, 0, sizeof big_hdr);
        memset(big_data, 0x5A, sizeof big_data);
        bh->magic = SMP_USER_MAGIC;
        bh->version = 1;
        bh->nz = 1;
        memcpy(bh->name, "BIGLOOP1", 8);
        bh->data_len = sizeof big_data;
        bh->zone[0].n = (uint32_t)sizeof big_data * 2u;
        bh->zone[0].rate = 65536;
        bh->crc = st_crc32(big_data, sizeof big_data);
        memcpy(flash_image + base, big_hdr, 512);
        memcpy(flash_image + base + 512, big_data, sizeof big_data);
        smp_user_scan(0);
        assert(usr_nz[0] == 1);
        memcpy(sec1_before, flash_image + base + 0x1000, sizeof sec1_before);

        a[0] = 0;
        request(ED_SMP_BEGIN, a, 1);
        assert(reply[6] == 0);
        for (off = 512; off <= 0x1000u; off += 256) {
            memset(chunk, 0xA5, sizeof chunk);
            a[0] = 0;
            u21(a + 1, off);
            n = pack(chunk, sizeof chunk, a + 4);
            request(ED_SMP_WRITE, a, n + 4);
            assert(reply[9] == 0);
        }
        assert(memcmp(flash_image + base + 0x1000, sec1_before, sizeof sec1_before) != 0);
        a[0] = 0;
        request(ED_SMP_BEGIN, a, 1);   /* abandon: must not resurrect corrupt sample */
        assert(reply[6] == 0);
        assert(usr_nz[0] == 0);
        /* Boot path: scan then recover — still empty, not a zombie usr_nz. */
        smp_user_scan(0);
        ed_smp_recover();
        assert(usr_nz[0] == 0);
        puts("smp begin-cancel: higher-sector mid-WRITE abandon fail-closed ok");
    }
    return 0;
}

#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-only
"""Compose or inspect a model-specific NIGHTLY package with its matching controller.

  package_nightly.py APP.fwsc ctl.img --model elite --controller-sha256 HASH --controller-size SIZE -o COMPLETE.fwsc
  package_nightly.py COMPLETE.fwsc --check --model elite --controller-sha256 HASH --controller-size SIZE

The reviewed controller pin must be supplied explicitly. No cached image, empty-controller
fallback, hardware access, license approval or publication is implied. JSON on stdout records
the actual checked output bytes. Composition and durable output reuse tools/add_ctl.py.
"""
import argparse
import hashlib
import json
import re
import struct
import sys
import zlib
from pathlib import Path

import add_ctl
import fm1_install
import fm1pkg_make as pm
import release_alloc
from firmware_build_labels import canonical_version, release_display, version_of_product

MODELS = {"elite": "SMK-37 Elite", "pro": "SMK-37 Pro"}


def sha256(data):
    return hashlib.sha256(data).hexdigest()


def _pin(expected_sha256, expected_size):
    if not isinstance(expected_sha256, str) or not re.fullmatch(r"[0-9a-f]{64}", expected_sha256):
        raise add_ctl.PkgError("controller SHA256 must be 64 lowercase hexadecimal characters")
    if type(expected_size) is not int or not add_ctl.HDR_SIZE <= expected_size <= add_ctl.BLE_SIZE:
        raise add_ctl.PkgError("controller size must be an exact image size between 68 and 65536 bytes")


def _embedded_version(product, model):
    """Legacy model_900 is unversioned. Any other identity must be the 9XXYYZZ codec."""
    if model not in MODELS:
        raise add_ctl.PkgError("NIGHTLY model must be elite or pro")
    if product == MODELS[model] + "_900":
        return None
    try:
        found = version_of_product(product, model)
    except (ValueError, TypeError, AttributeError) as exc:
        raise add_ctl.PkgError(f"package model {product!r} does not match {model}") from exc
    if found is None:
        raise add_ctl.PkgError(f"package model {product!r} does not match {model}")
    return found


def _require_allocated_version(version, ledger):
    """A numeric identity must already exist in the ledger. Legacy model_900 stays unversioned."""
    if version is None:
        return
    path = Path(ledger) if ledger is not None else Path("releases/openbeta/ledger.json")
    try:
        data = release_alloc._load(path)
    except release_alloc.ReleaseError as exc:
        raise add_ctl.PkgError(str(exc)) from exc
    if not any(item.get("version") == version for item in data["allocations"]):
        raise add_ctl.PkgError("firmware version is not allocated")


def _package(raw, model, expected_version=None, ledger=None):
    """Strict current NIGHTLY structure, without weakening the legacy composition path."""
    if model not in MODELS:
        raise add_ctl.PkgError("NIGHTLY model must be elite or pro")
    product, logical = add_ctl.logical_of(raw)
    version = _embedded_version(product, model)
    if expected_version is not None:
        try:
            expected_version = canonical_version(expected_version)
        except ValueError as exc:
            raise add_ctl.PkgError(str(exc)) from exc
        if version != expected_version:
            raise add_ctl.PkgError(
                f"package model {product!r} does not match firmware version {expected_version}")
    _require_allocated_version(version, ledger)
    if problem := fm1_install.package_damage(logical):
        raise add_ctl.PkgError(f"package integrity: {problem}")
    hdr = add_ctl._dec(logical[:0x40])
    if struct.unpack_from("<I", hdr, 4)[0] != len(logical):
        raise add_ctl.PkgError("package declared length does not match its bytes")
    count = struct.unpack_from("<H", hdr, 8)[0]
    if count != 2:
        raise add_ctl.PkgError("NIGHTLY package must contain exactly flash.bin and ota.bin")
    previous_end = 0x40 + count * 0x50
    flash = None
    for i, (typ, name) in enumerate(((0, b"flash.bin"), (100, b"ota.bin"))):
        entry = add_ctl._dec(logical[0x40 + i * 0x50:0x40 + (i + 1) * 0x50])
        if struct.unpack_from("<H", entry, 0)[0] != typ or entry[0x40:0x50].split(b"\0")[0] != name:
            raise add_ctl.PkgError("NIGHTLY package file layout is not flash.bin followed by ota.bin")
        off, size = struct.unpack_from("<II", entry, 8)
        if off < previous_end or off % 0x100 or size == 0:
            raise add_ctl.PkgError("NIGHTLY package file range is invalid")
        previous_end = off + size
        if typ == 0:
            flash = logical[off:off + size]
        if typ == 100 and fm1_install.LOADER_MARK not in logical[off:off + size]:
            raise add_ctl.PkgError("NIGHTLY package has no Felucca update loader")
    # Bound the legacy decoder's pointers before calling it. An otherwise CRC-consistent
    # malformed package must produce a package refusal, not index beyond a sliced buffer.
    if len(flash) != pm.BOARDS["smk37"][0]:
        raise add_ctl.PkgError("NIGHTLY SMK-37 flash size/layout is invalid")
    isd = add_ctl._dec(flash[64:96])
    if not isd[16:32].startswith(b"isd_config.ini"):
        raise add_ctl.PkgError("NIGHTLY package has no isd_config.ini in the flash head")
    key_off, key_size = struct.unpack_from("<II", isd, 4)
    if key_size < 32 or key_off < 0xA0 or key_off + key_size > 0x4000:
        raise add_ctl.PkgError("NIGHTLY chip-key range is outside the flash head")
    key = pm.chipkey_decode(bytes(flash[key_off:key_off + 32]))
    area_head = bytearray(flash[0x4000:0x4020])
    pm.sfc(area_head, 0, 32, 0, key)
    blk = struct.unpack_from("<I", area_head, 8)[0]
    area_size = (blk + 31) & ~31
    if blk < 0x120 + add_ctl.SMK_SLOT or area_size > pm.SLOTMAP_OFF - 0x4000:
        raise add_ctl.PkgError("NIGHTLY SMK-37 app area range is invalid")
    st = add_ctl._open(logical)
    area, blk = st["area"], st["blk"]
    if len(st["flash"]) != pm.BOARDS["smk37"][0] or blk < 0x120 + add_ctl.SMK_SLOT or len(area) != st["n"]:
        raise add_ctl.PkgError("NIGHTLY SMK-37 app area size/layout is invalid")
    if pm.crc16(area[2:32]) != struct.unpack_from("<H", area, 0)[0]:
        raise add_ctl.PkgError("app area header CRC")
    if pm.crc16(area[32:blk]) != struct.unpack_from("<H", area, 2)[0]:
        raise add_ctl.PkgError("app area data CRC")
    if pm.crc16(area[34:64]) != struct.unpack_from("<H", area, 32)[0]:
        raise add_ctl.PkgError("app.bin entry CRC")
    if pm.crc16(area[0x120:0x120 + add_ctl.SMK_SLOT]) != struct.unpack_from("<H", area, 34)[0]:
        raise add_ctl.PkgError("app.bin data CRC")
    expected_map = pm.slotmap_blob(pm.SLOTMAP["smk37"])
    if st["flash"][pm.SLOTMAP_OFF:pm.SLOTMAP_OFF + len(expected_map)] != expected_map:
        raise add_ctl.PkgError("NIGHTLY package has no matching current SMK-37 sample slot map")
    return product, logical, st


def inspect(raw, model, expected_sha256, expected_size, expected_version=None, ledger=None):
    """Return byte-derived metadata only after the embedded controller matches its review pin."""
    _pin(expected_sha256, expected_size)
    product, logical, _ = _package(raw, model, expected_version, ledger)
    version = _embedded_version(product, model)
    ctl = add_ctl.controller_of(logical)
    if ctl is None:
        raise add_ctl.PkgError("NIGHTLY package is missing its bundled Bluetooth controller")
    if len(ctl) != expected_size or sha256(ctl) != expected_sha256:
        raise add_ctl.PkgError("bundled Bluetooth controller size/SHA256 does not match the reviewed pin")
    block = ctl + b"\xff" * (add_ctl.BLE_SIZE - len(ctl))
    return {
        "schema": "x0x37-bundled-controller-v1",
        "model": model,
        "product": product,
        "firmware_version": version,
        "release_display": None if version is None else release_display(version),
        "size": len(raw),
        "sha256": sha256(raw),
        "controller_strategy": "bundled",
        "controller_sha256": sha256(ctl),
        "controller_size": len(ctl),
        "controller": {
            "strategy": "bundled", "bundled": True,
            "size": len(ctl), "sha256": sha256(ctl),
            "crc32": f"{struct.unpack_from('<I', ctl, 16)[0]:08x}",
            "block_size": add_ctl.BLE_SIZE,
            "block_crc32": f"{zlib.crc32(block):08x}",
            "flash_offset": pm.BLE_LO,
            "header_version": add_ctl.HDR_VERSION, "abi": add_ctl.ABI,
        },
    }


def compose(raw, ctl, model, expected_sha256, expected_size, expected_version=None, ledger=None):
    """Build one complete package; the exact controller is mandatory before any output write."""
    _pin(expected_sha256, expected_size)
    _package(raw, model, expected_version, ledger)
    if not isinstance(ctl, (bytes, bytearray)):
        raise add_ctl.PkgError("a matching Bluetooth controller image is required")
    if len(ctl) != expected_size or sha256(ctl) != expected_sha256:
        raise add_ctl.PkgError("Bluetooth controller size/SHA256 does not match the reviewed pin")
    if struct.unpack_from("<I", ctl, 12)[0] != len(ctl):
        raise add_ctl.PkgError("controller pin must cover declared image bytes without padding")
    if problem := add_ctl.ctl_problem(ctl):
        raise add_ctl.PkgError(f"Bluetooth controller: {problem}")
    output = add_ctl.add(raw, ctl)
    receipt = inspect(output, model, expected_sha256, expected_size, expected_version, ledger)
    if len(output) != len(raw) or add_ctl.add(output, None) != add_ctl.add(raw, None):
        raise add_ctl.PkgError("controller composition changed bytes outside the controller/checksum fields")
    return output, receipt


def main(argv=None):
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("package", type=Path)
    ap.add_argument("controller", type=Path, nargs="?")
    ap.add_argument("--model", choices=MODELS, required=True)
    ap.add_argument("--controller-sha256", required=True)
    ap.add_argument("--controller-size", type=int, required=True)
    ap.add_argument("--firmware-version", help="require this canonical X.Y.Z machine identity")
    ap.add_argument("--ledger", type=Path, help="open-beta ledger; default releases/openbeta/ledger.json")
    ap.add_argument("--check", action="store_true", help="inspect an already complete package; write no package")
    ap.add_argument("-o", "--out", type=Path)
    args = ap.parse_args(argv)
    if args.check and (args.controller is not None or args.out is not None):
        ap.error("--check takes a complete package only; omit controller and output")
    if not args.check and (args.controller is None or args.out is None):
        ap.error("composition requires PACKAGE CONTROLLER -o OUTPUT; no Bluetooth-less NIGHTLY output")
    try:
        raw = args.package.read_bytes()
        if args.check:
            receipt = inspect(raw, args.model, args.controller_sha256, args.controller_size,
                              args.firmware_version, args.ledger)
        else:
            output, receipt = compose(raw, args.controller.read_bytes(), args.model,
                                      args.controller_sha256, args.controller_size, args.firmware_version,
                                      args.ledger)
            add_ctl.write_package(args.out, output)
            # Read the committed name too, not just the temporary file checked by write_package.
            committed = args.out.read_bytes()
            if committed != output:
                raise OSError("output replacement completed but its bytes changed before readback; inspect before retrying")
            inspect(committed, args.model, args.controller_sha256, args.controller_size,
                    args.firmware_version, args.ledger)
        print(json.dumps(receipt, indent=2, sort_keys=True))
        return 0
    except (OSError, add_ctl.PkgError, ValueError, struct.error) as exc:
        print(f"package_nightly: {exc}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-only
"""Reuse the headers tools/build.py generates when their inputs are unchanged.

A nightly build renders the font, the 909 samples, and the built-in break bank
before it compiles. Those outputs follow the generators, the assets, the 909
sources, and the host compiler. They do not follow the rest of the firmware.
The cache key is a content hash of those inputs. A changed byte misses.
Set X0X_GEN_CACHE=0 to generate every time. Any other value is the cache directory.
"""
import hashlib
import os
import re
import shutil
import subprocess
from pathlib import Path

SRC = Path(__file__).resolve().parents[1]
HEADERS = ("felucca_font.h", "x0x_drum_samples.h", "x0x_drum_tables.h", "x0x_break_bank.h")
GENERATED = set(HEADERS)
INCLUDE = re.compile(r'^\s*#\s*include\s+"([^"]+)"', re.M)
SEARCH = (SRC / "firmware" / "src", SRC / "firmware" / "src" / "dsp")
TOOLS = (
    "tools/gen_font.py",
    "tools/gen_drum_samples.py",
    "tools/gen_break_bank.py",
    "tools/gen_builtin_break.sh",
    "tools/gen_builtin_break.c",
    "tools/sampleio.py",
    "tools/break_pack.py",
)
ROOTS = (
    SRC / "tools" / "gen_builtin_break.c",
    SRC / "firmware" / "src" / "dsp" / "drum909.c",
)


def cache_root():
    """None disables the cache. An empty X0X_GEN_CACHE uses the default directory."""
    value = os.environ.get("X0X_GEN_CACHE")
    if value == "0":
        return None
    if value:
        return Path(value)
    return Path.home() / ".cache" / "x0x-gen"


def _add(hasher, label, data):
    hasher.update(label.encode())
    hasher.update(b"\0")
    hasher.update(data)
    hasher.update(b"\0")


def _add_file(hasher, path):
    path = Path(path)
    hasher.update(str(path).encode())
    hasher.update(b"\0")
    with path.open("rb") as stream:
        for chunk in iter(lambda: stream.read(1 << 20), b""):
            hasher.update(chunk)
    hasher.update(b"\0")


def _sources():
    """Local headers the break-bank compiler reads, plus the generators."""
    found = []
    stack = [path for path in ROOTS if path.is_file()]
    while stack:
        path = stack.pop()
        if path in found or path.name in GENERATED or not path.is_file():
            continue
        found.append(path)
        try:
            text = path.read_text(encoding="utf-8", errors="replace")
        except OSError:
            continue
        for name in INCLUDE.findall(text):
            for base in (path.parent, *SEARCH):
                candidate = base / name
                if candidate.is_file() and candidate.name not in GENERATED:
                    stack.append(candidate)
                    break
    for rel in TOOLS:
        path = SRC / rel
        if path.is_file() and path not in found:
            found.append(path)
    return found


def _font_files():
    files = []
    dirs = [SRC / "assets" / "fonts"]
    dirs += [Path(p) for p in os.environ.get("X0X_FONT_DIRS", "").split(":") if p]
    for directory in dirs:
        if not directory.is_dir():
            continue
        for path in sorted(directory.iterdir()):
            if path.suffix.lower() in {".bdf", ".ttf", ".otf", ".ttc"} and path.is_file():
                files.append(path)
    return files


def _wavs(directory):
    directory = Path(directory)
    if not directory.is_dir():
        return []
    return sorted(path for path in directory.rglob("*") if path.is_file() and path.suffix.lower() == ".wav")


def _font_renderer_inputs():
    """Version the libraries which turn font bytes into compiled glyph headers.

    A source/assets hash alone cannot distinguish Pillow, FreeType or libraqm
    changes. If this runtime cannot be identified, bypass rather than reuse
    an incompatible generated-header cache entry.
    """
    try:
        import PIL
        from PIL import features
        raqm = bool(features.check("raqm"))
        return {
            "pillow": PIL.__version__,
            "freetype2": features.version_module("freetype2") or "unavailable",
            "raqm-enabled": "1" if raqm else "0",
            "raqm-version": (features.version_feature("raqm") or "unavailable") if raqm else "disabled",
        }
    except (ImportError, AttributeError, ValueError, RuntimeError) as exc:
        raise OSError("cannot identify Pillow font renderer for generated cache") from exc


def fingerprint():
    """Hash generate() inputs: compiler, assets, source, and font renderer."""
    hasher = hashlib.sha256()
    for label, value in sorted(_font_renderer_inputs().items()):
        _add(hasher, "font-renderer-" + label, str(value).encode())
    for key in ("X0X_FONTSET", "X0X_FONT_DIRS", "X0X_BREAK_BANK", "X0X_FACTORY_BREAKS", "CC"):
        _add(hasher, key, os.environ.get(key, "").encode())
    mode = "bank" if os.environ.get("X0X_BREAK_BANK") else (
        "factory" if os.environ.get("X0X_FACTORY_BREAKS") == "1" else "none")
    _add(hasher, "break-bank-mode", mode.encode())
    cc = os.environ.get("CC", "cc")
    resolved = shutil.which(cc) or cc
    _add(hasher, "cc-path", resolved.encode())
    version = subprocess.run([cc, "--version"], capture_output=True, text=True, timeout=30)
    if version.returncode != 0:
        raise OSError("host compiler did not report its version")
    _add(hasher, "cc-version", (version.stdout + version.stderr).encode())
    for path in _sources():
        _add_file(hasher, path)
    for path in _font_files():
        _add_file(hasher, path)
    for path in _wavs(SRC / "assets" / "909"):
        _add_file(hasher, path)
    bank = os.environ.get("X0X_BREAK_BANK")
    if bank:
        for path in sorted(p for p in Path(bank).rglob("*") if p.is_file()):
            _add_file(hasher, path)
    return hasher.hexdigest()


def _digest(directory):
    """Content digest. The directory path is not part of it, so a renamed entry still matches."""
    hasher = hashlib.sha256()
    for name in HEADERS:
        path = directory / name
        if not path.is_file() or path.stat().st_size == 0:
            return ""
        hasher.update(name.encode())
        hasher.update(b"\0")
        with path.open("rb") as stream:
            for chunk in iter(lambda: stream.read(1 << 20), b""):
                hasher.update(chunk)
        hasher.update(b"\0")
    return hasher.hexdigest()


def _ready(directory):
    done = directory / "DONE"
    try:
        return done.is_file() and done.read_text(encoding="utf-8").strip() == _digest(directory)
    except OSError:
        return False


def restore(gen_dir):
    """Copy a complete cache entry into gen_dir. A miss or a damaged entry returns False."""
    root = cache_root()
    if root is None:
        return False
    try:
        source = root / fingerprint()
    except (OSError, subprocess.SubprocessError):
        return False
    if not _ready(source):
        return False
    gen_dir = Path(gen_dir)
    gen_dir.mkdir(parents=True, exist_ok=True)
    for name in HEADERS:
        shutil.copyfile(source / name, gen_dir / name)
    if _digest(gen_dir) != (source / "DONE").read_text(encoding="utf-8").strip():
        return False
    return True


def store(gen_dir):
    """Save gen_dir when it holds every header. Leave an existing good entry alone."""
    root = cache_root()
    if root is None:
        return
    gen_dir = Path(gen_dir)
    if any(not (gen_dir / name).is_file() for name in HEADERS):
        return
    try:
        key = fingerprint()
    except (OSError, subprocess.SubprocessError):
        return
    dest = root / key
    if _ready(dest):
        return
    root.mkdir(parents=True, exist_ok=True)
    temporary = root / f".{key}.{os.getpid()}.tmp"
    if temporary.exists():
        shutil.rmtree(temporary)
    temporary.mkdir()
    try:
        for name in HEADERS:
            shutil.copyfile(gen_dir / name, temporary / name)
        (temporary / "DONE").write_text(_digest(temporary) + "\n", encoding="utf-8")
        if dest.exists() and not _ready(dest):
            shutil.rmtree(dest)
        if _ready(dest):
            shutil.rmtree(temporary)
            return
        os.rename(temporary, dest)
    except Exception:
        shutil.rmtree(temporary, ignore_errors=True)
        if not _ready(dest):
            raise

// SPDX-License-Identifier: GPL-3.0-only
// F03: installKeepingSlots must fail closed when the sample-slot layout probe fails.
// No real MIDI, no device write. Models today's silent skip (.catch(() => null) then install)
// and asserts the repaired rule. Run from the repo root: node web/test_f03_slot_probe.mjs
import { Updater, pack7, sameKeyboard } from "./fm1ota.js";
import { installKeepingSlots, packageSlotMap } from "./x0x_breaks.js";

let bad = 0;
const ok = (c, what) => { console.log(`${what.padEnd(72)} ${c ? "ok" : "FAIL"}`); if (!c) bad++; };
const HS = [0xF0, 0x00, 0x32, 0x45, 0x00, 0x00, 0x00, 0x40, 0x7F, 0xF7];
const UPGRADE = [0xF0, 0x22, 0x24, 0x35, 0x7F, 0xF7];
const eq = (a, b) => a.length === b.length && a.every((v, i) => v === b[i]);
const PRODUCT = "SMK-37 Pro_900";

function packageOf(product) {
  const raw = Uint8Array.from({ length: 0x2000 + 20 }, (_, i) => (i * 7) & 0xFF);
  for (let i = 0; i < 20; i++) raw[i * 0x30 + 0x2F] = i < product.length ? (product.charCodeAt(i) + i + 1) & 0xFF : 0x7D;
  raw.set([..."FELUCCA-LOADER-1"].map((c) => c.charCodeAt(0)), 0x1800);
  const logical = [];
  for (let i = 0; i < 20; i++) logical.push(...raw.subarray(i * 0x30, i * 0x30 + 0x2F));
  return { raw, image: Uint8Array.from([...logical, ...raw.subarray(20 * 0x30)]) };
}

/** Simulated SMK: answers identity and the update protocol; slot probe is controlled. */
class FakeSMK {
  constructor(image, { answerSlots = "empty" } = {}) {
    this.image = image;
    this.answerSlots = answerSlots; // "empty" | "mute" | "bad"
    this.upgrades = 0;
    this.access = { inputs: new Map(), outputs: new Map() };
    this.boot(PRODUCT, "SMK-37 Pro"); // Current X0X must answer SMP_INFO; stock _016 has a separate exemption.
  }
  boot(identity, name) {
    this.identity = identity;
    this.waiting = null;
    this.queue = [];
    for (const m of [this.access.inputs, this.access.outputs]) {
      for (const p of m.values()) p.state = "disconnected";
      m.clear();
    }
    const id = Math.random().toString(36).slice(2);
    this.input = { id: "i" + id, name, state: "connected", onmidimessage: null, open: async () => {} };
    this.output = {
      id: "o" + id, name, state: "connected", open: async () => {},
      send: (d) => {
        if (this.output.state !== "connected") throw new Error("InvalidStateError");
        setImmediate(() => this.rx(Array.from(d)));
      },
    };
    this.access.inputs.set(this.input.id, this.input);
    this.access.outputs.set(this.output.id, this.output);
  }
  tx(bytes) {
    const i = this.input;
    setImmediate(() => { if (i.state === "connected" && i.onmidimessage) i.onmidimessage({ data: Uint8Array.from(bytes) }); });
  }
  rx(d) {
    if (d[1] === 0x7D && d[2] === 0x46 && d[3] === 0x4C) {
      if (this.answerSlots === "mute") return;
      if (d[4] === 15) {
        if (this.answerSlots === "bad") {
          this.tx([0xF0, 0x7D, 0x46, 0x4C, 15, 0xF7]); // short / unparsable
          return;
        }
        // Valid empty layout: one 80 KiB slot with zero zones, empty name and zero used KiB.
        this.tx([0xF0, 0x7D, 0x46, 0x4C, 15, 1, 80, 0, 0, 0, 0xF7]);
      }
      return;
    }
    if (eq(d, HS)) {
      const t = [...new TextEncoder().encode(this.identity)];
      const payload = [...t, ...new Array(27 - t.length).fill(0)];
      const body = [0, 0x59, 0x11, 27, 0, 0, ...payload, ~payload.reduce((sum, b) => sum + b, 0) & 255];
      this.tx([0xF0, ...pack7(body), 0xF7]);
    } else if (eq(d, UPGRADE)) {
      this.upgrades++;
      this.queue = this.identity.startsWith("ota-")
        ? [...Array.from({ length: 6 }, (_, k) => [k * 512, 512]), [0xF0000000, 8]]
        : [[0, 64], [0x40, 160], [0x1000, 512], [0xE0000000, 8]];
      this.next();
    } else if (this.waiting) {
      const u = (() => {
        const out = [];
        const a = d.slice(1, -1);
        for (let i = 0; i < a.length;) {
          const m = a[i++];
          for (let j = 0; j < 7 && i < a.length; j++) out.push(a[i++] | ((m >> j) & 1) << 7);
        }
        return out;
      })();
      const [addr, len] = this.waiting;
      const want = addr >= 0xE0000000 ? [...new TextEncoder().encode("success"), 0]
        : Array.from(this.image.subarray(addr, addr + len));
      void u; void want;
      this.waiting = null;
      if (addr === 0xE0000000) setTimeout(() => this.boot("ota-SMK-37 Pro_900", "Felucca Update"), 20);
      else if (addr === 0xF0000000) setTimeout(() => this.boot(PRODUCT, "SMK-37 Pro"), 20);
      else this.next();
    }
  }
  next() {
    const r = this.queue.shift();
    if (!r) return;
    this.waiting = r;
    const [addr, len] = r;
    const u = [0, 0x59, 0x30, 0, 0, 0, 0, addr & 0xFF, (addr >>> 8) & 0xFF, (addr >>> 16) & 0xFF, (addr >>> 24) & 0xFF, len & 0xFF, len >> 8, 0];
    let s = 0;
    for (let i = 6; i < 14; i++) s += u[i];
    u.push(~s & 0xFF);
    this.tx([0xF0, ...pack7(u), 0xF7]);
  }
}

/** Pre-repair twin: .catch(() => null) then install anyway. */
async function silentSkipInstall(up, image, product, board, hooks) {
  const h = Object.assign({ step() {}, say() {}, save() {}, progress() {}, sameKeyboard: () => true }, hooks);
  const fail = (code, msg, detail = "") => Object.assign(new Error(msg), { code, detail });
  const { readSlotLayout } = await import("./x0x_breaks.js");
  const dev = await up.find((id) => !/^ota-/i.test(id.model));
  if (dev && !h.sameKeyboard(dev.id.model, product.split("_")[0])) dev.link.close();
  else if (dev) {
    try {
      const layout = await readSlotLayout(dev.link, 200, 1).catch(() => null);
      if (layout && layout.slots.some((sl) => sl.nz)) {
        throw fail("unexpected", "silent-skip model expected empty/null layout");
      }
    } finally { dev.link.close(); }
  }
  return up.install(image, product, h.step);
}

async function main() {
  const pkg = packageOf(PRODUCT);
  ok(packageSlotMap(pkg.image).length >= 0, "fixture package loads");

  // Model: mute probe + silent skip still installs (today's bug).
  {
    const dev = new FakeSMK(pkg.image, { answerSlots: "mute" });
    const ran = await silentSkipInstall(new Updater(dev.access), pkg.image, PRODUCT, "smk", { sameKeyboard });
    ok(ran === PRODUCT && dev.upgrades === 2,
       "model: pre-repair mute probe still installs (silent skip)");
  }

  // Repaired: mute probe fails closed before write.
  {
    const dev = new FakeSMK(pkg.image, { answerSlots: "mute" });
    const err = await installKeepingSlots(new Updater(dev.access), pkg.image, PRODUCT, "smk", {
      sameKeyboard,
    }).then(() => null, (e) => e);
    ok(err && err.code === "slotlayout" && /Cannot verify the current sample layout before install/.test(err.message)
       && dev.upgrades === 0,
       "installKeepingSlots: mute probe -> slotlayout error, nothing written");
  }

  // Successful empty layout still installs.
  {
    const dev = new FakeSMK(pkg.image, { answerSlots: "empty" });
    const res = await installKeepingSlots(new Updater(dev.access), pkg.image, PRODUCT, "smk", {
      sameKeyboard,
    });
    ok(res && res.product === PRODUCT && res.move === null && dev.upgrades === 2,
       "installKeepingSlots: successful empty layout installs without backup");
  }

  // Unparsable layout also fails closed.
  {
    const dev = new FakeSMK(pkg.image, { answerSlots: "bad" });
    const err = await installKeepingSlots(new Updater(dev.access), pkg.image, PRODUCT, "smk", {
      sameKeyboard,
    }).then(() => null, (e) => e);
    ok(err && err.code === "slotlayout" && /short SMP_INFO reply/.test(err.message) && dev.upgrades === 0,
       "installKeepingSlots: bad layout parse -> slotlayout error, nothing written");
  }

  process.exit(bad ? 1 : 0);
}

main().catch((e) => { console.error(e); process.exit(1); });

/* SPDX-License-Identifier: GPL-3.0-only
 * Boot, audio ISR and main loop adapted from Felucca's main.c / audio.c, Copyright (C) 2026
 * Leo Kuroshita (@kurogedelic), Hugelton Instruments. */
/* X0X on the FM-1: boot (WDT first, boot-loop guard, guards), LCD, input (TIMER5 10 kHz),
 * audio (ALNK0), USB; then the main loop: UI at ~60 frames/s, input polled in between. */
extern uint32_t _data_start[], _data_end[], _data_load[], _bss_start[], _bss_end[];
extern uint32_t _pool_start[], _pool_end[], _rt_start[], _rt_end[], _rt_load[], _c1_start[], _c1_end[], _c1_load[];

/* --------------------------------------------------------------- audio --- */
/* X0X: 512-frame halves (11.6 ms; Felucca 256). The render runs inside the DMA's deadline, and a
 * busy pattern averaging ~80 % ran over it about one half in 300 (a heavy step): a dropped half.
 * Twice the half averages a heavy step over twice the time, for one more half of latency. */
#define HALF_FRAMES 512u                    /* I2S half buffer: 11.6 ms at 44.1 kHz */
#define HALF_WORDS (HALF_FRAMES * 2u)
#define REND_FRAMES 256u                    /* engine_render's most per call */
#if FELUCCA_UAC
_Static_assert(REND_FRAMES == UA_HALF, "usb.c sizes the USB audio ring band for this block");
#endif
static int32_t abuf[2u * HALF_WORDS] __attribute__((aligned(4)));

#define DBG_MAGIC 0x44424731u                       /* "DBG1": read with `fm1t memr` */
struct x0x_dbg {
    uint32_t magic, halves, max_us, nested, in_audio, late, timer_irqs, ui_frames;
    uint32_t last_us, cpu_q8, boots, stage;
    uint32_t crash_seen;                            /* the crash count already reported at a boot */
} x0x_dbg __attribute__((section(".noinit")));
static uint8_t safe_mode;
#if X0X_DEBUG
/* development: the slowest block since boot, taken apart (read over USB: tools/fm1_debug.py) */
extern volatile uint32_t eng_dbg_wait, eng_dbg_nsub;
static volatile uint32_t dbg_tmr;                   /* 24 MHz ticks of TIMER5 nested in the render */
struct x0x_worst_s {
    uint32_t magic, us, wait, tmr, nsub, half_no, over90, over100, blocks, late_in;
} x0x_worst;
#endif                           /* two failed boots: no audio, USB on (safe_main) */

static void render_block(int32_t *o)                /* ALNK0: one half, measured */
{
    uint32_t t0 = fm1_ticks(), us, budget = HALF_FRAMES * 1000000u / FS;
    x0x_dbg.in_audio = 1;
#if FELUCCA_UAC
    uac_render_start();
#endif
    {
        uint32_t k;
        for (k = 0; k < HALF_FRAMES; k += REND_FRAMES) {
            engine_render(o + 2u * k, REND_FRAMES);
#if FELUCCA_UAC
            uac_tap(o + 2u * k, REND_FRAMES);       /* the USB audio input: the same master output */
#endif
            engine_volume(o + 2u * k, REND_FRAMES);     /* USB AUDIO FULL: the MASTER knob after the tap */
        }
    }
    us = (fm1_ticks() - t0) / FM1_TICKS_PER_US;
#if X0X_DEBUG
    x0x_worst.magic = 0x57525354u;                  /* "WRST" */
    x0x_worst.blocks++;
    if (us * 100u > budget * 90u)
        x0x_worst.over90++;
    if (us > budget)
        x0x_worst.over100++;
    if (us > x0x_worst.us) {
        x0x_worst.us = us;
        x0x_worst.wait = eng_dbg_wait;
        x0x_worst.tmr = dbg_tmr;
        x0x_worst.nsub = eng_dbg_nsub;
        x0x_worst.half_no = x0x_dbg.halves;
    }
    eng_dbg_wait = eng_dbg_nsub = 0;
    dbg_tmr = 0;
#endif
    x0x_dbg.cpu_q8 = (x0x_dbg.cpu_q8 * 15u + (us * 256u) / budget) / 16u;
    audio_cpu_pct = (x0x_dbg.cpu_q8 * 100u) >> 8;
    if (us * 100u / budget > audio_peak_pct)
        audio_peak_pct = us * 100u / budget;        /* the PERF screen's peak (read and reset) */
    engine_load(us * 100u / budget, HALF_FRAMES);
    x0x_dbg.halves++;
    x0x_dbg.last_us = us;
    if (us > x0x_dbg.max_us)
        x0x_dbg.max_us = us;
    x0x_dbg.in_audio = 0;
}

void fm1_alnk0_irq(void)                            /* via isr_alnk0 (hal/fm1_isr.S) */
{
    uint8_t p = fm1_audio_pending();
    fm1_audio_ack_aux(p);
    if (p & FM1_AUDIO_HALF) {
        uint32_t half = fm1_audio_free_half();
        render_block(&abuf[half * HALF_WORDS]);
        fm1_audio_ack_half();
        if (fm1_audio_free_half() != half) {
#if X0X_DEBUG
            x0x_worst.late_in++;
#endif
            x0x_dbg.late++;                         /* the DMA moved on while we rendered */
            audio_xruns++;
        }
    }
}
extern void isr_alnk0(void);

static void audio_init(void)
{
    uint32_t i;
    for (i = 0; i < 2u * HALF_WORDS; i++)
        abuf[i] = 0;
    fm1_audio_init(abuf, HALF_WORDS, isr_alnk0, 3);
}

static void audio_silence(void)                     /* IRQs off (flash erase): the DMA would loop stale audio */
{
    uint32_t i;
    for (i = 0; i < sizeof abuf / sizeof abuf[0]; i++)
        abuf[i] = 0;
}

/* ------------------------------------------------------------ timer --- */
static uint8_t usb_due;
void fm1_timer5_irq(void)
{
    static uint32_t sub;
#if X0X_DEBUG
    uint32_t tt0 = fm1_ticks();
#endif
    fm1_timer5_ack();
#if X0X_BLE
    fm1_t5w_begin();                                /* test 22: who changes this frame */
#endif
    x0x_dbg.timer_irqs++;
    if (x0x_dbg.in_audio)
        x0x_dbg.nested++;
    fm1_input_tick();
#if X0X_BLE
    fm1_t5w_check(1u, fm1_ms);
#endif
    /* 2 kHz: all USB SIE traffic lives here. This ISR now nests into the audio render (so the key
     * matrix keeps its rhythm, below); USB shares the MIDI queues with the audio ISR, so a poll that
     * falls inside the render waits for the first tick outside it, as it did before the nesting. */
    if (sub % 5u == 0u) {
        usb_due = 1;
#if FELUCCA_UAC
        /* the USB audio stream cannot wait for the render (one packet per 1 ms frame, a render takes
         * up to ~11.6 ms): it runs nested too. It touches only EP4 (INDEX is set on every access) and
         * the consumer side of its ring, and usb_poll never runs nested, so the two never interleave */
        if (x0x_dbg.in_audio)
            uac_service();
#endif
    }
    if (usb_due && !x0x_dbg.in_audio) {
        usb_due = 0;
        usb_poll();
#if X0X_TRS
        uart_midi_poll();                           /* the TRS jack: same context, same queue */
#endif
#if X0X_BLE
        fm1_t5w_check(2u, fm1_ms);
        ble_service();                              /* Bluetooth MIDI: same context, same queue */
        fm1_t5w_check(3u, fm1_ms);
#endif
    }
    if (++sub == 10u)
        sub = 0;
    {
        static uint32_t last, acc;
        uint32_t now = fm1_ticks();
        acc += now - last;
        last = now;
        while (acc >= 1000u * FM1_TICKS_PER_US) {
            acc -= 1000u * FM1_TICKS_PER_US;
            fm1_ms++;
        }
    }
#if X0X_BLE
    fm1_t5w_check(4u, fm1_ms);
    fm1_t5w_end(fm1_ms);
#endif
#if X0X_DEBUG
    if (x0x_dbg.in_audio)
        dbg_tmr += fm1_ticks() - tt0;
#endif
}
extern void isr_timer5(void);

