static volatile uint8_t apc_led_velocity[SMK_APC40_CLIP_COUNT];
static volatile uint8_t apc_cell_flags[SMK_APC40_CLIP_COUNT];   /* off pending, queued */
static volatile uint8_t apc_led_channel[SMK_APC40_CLIP_COUNT];
